function fillEnclosedPockets(board: string[][]): void {
  const R = board.length, C = board[0].length;
  const reachesEdge = (sr: number, sc: number): boolean => {
    const seen = new Set<number>([sr * C + sc]);
    const stack = [[sr, sc]];
    while (stack.length) {
      const [r, c] = stack.pop()!;
      if (r === 0 || c === 0 || r === R - 1 || c === C - 1) return true;
      for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
        if (board[nr][nc] === "." && !seen.has(nr * C + nc)) { seen.add(nr * C + nc); stack.push([nr, nc]); }
      }
    }
    return false;
  };
  const fill: number[][] = [];
  for (let r = 0; r < R; r++)
    for (let c = 0; c < C; c++)
      if (board[r][c] === "." && !reachesEdge(r, c)) fill.push([r, c]);
  for (const [r, c] of fill) board[r][c] = "#"; // only after every cell is decided
}

