        def reaches_edge(sr, sc):
            seen, stack = {(sr, sc)}, [(sr, sc)]
            while stack:
                r, c = stack.pop()
                if r == 0 or c == 0 or r == R - 1 or c == C - 1:
                    return True
                for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                    if board[nr][nc] == "." and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            return False

        fill = [(r, c) for r in range(R) for c in range(C) if board[r][c] == "." and not reaches_edge(r, c)]
        for r, c in fill:  # only after every cell is decided
            board[r][c] = "#"

