function fillEnclosedPockets(board: string[][]): void {
  const R = board.length, C = board[0].length;
  const queue: number[][] = [];
  const seed = (r: number, c: number) => {
    if (board[r][c] === ".") { board[r][c] = "S"; queue.push([r, c]); }
  };
  for (let r = 0; r < R; r++) { seed(r, 0); seed(r, C - 1); }
  for (let c = 0; c < C; c++) { seed(0, c); seed(R - 1, c); }
  for (let head = 0; head < queue.length; head++) {
    const [r, c] = queue[head];
    for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
      if (nr >= 0 && nc >= 0 && nr < R && nc < C && board[nr][nc] === ".") {
        board[nr][nc] = "S"; // safe: connected to the edge
        queue.push([nr, nc]);
      }
    }
  }
  for (let r = 0; r < R; r++)
    for (let c = 0; c < C; c++)
      board[r][c] = board[r][c] === "S" ? "." : "#"; // unreached "." cells are enclosed
}

